	title 'QuickDraw Pictures--Slice Part'****************************************************************** Copyright (C)* All Rights Reserved* Apple Computer, Inc. 1986-1989*** Pictures--Slice Part** This contains the	routines which need	the slice equates.** Change History** Version 2.0    May 8, 1987    Steven E. Glass**    Error handling	added for get and put calls.*** Version 2.4	27 May 88	Steven E. Glass** Bug in pixel map recording.  If SrcRect was bigger than bounds* rect, used src rect to determine number of lines to put into * picture.  Should have used the adjusted bounds rect.** 6/11/89	Mensch** Remove reference to WideOpen in copybits and make a local version* of same so that we can properly use pixelmaps in pictures when we call drawpicture.* I wonder how many more bugs like this we have...*****************************************************************	include 'all.macros'	include 'special.macros'	include '::qd:qdequates:core.globals1'	include '::qd:qdequates:core.globals2'	include '::qd:qdequates:region.equs'	include '::qd:qdequates:slice.equs'	include '::qd:qdequates:qd.data.asm'	include 'play.equs'***************************************************	Imports	         ***************************************************	Import GetPicWord	Import DerefTempDataPtr	Import PutPicWord	Import CallPutPic	Import PutPicRgnC	Import CallGetPic	Import MapThisRect	Import GetPicRgn	Import MapThisRgn	Import MyWNewHandle	Import CallGetPic	Import CallStdPlay***************************************************	Entries	         ***************************************************	Entry WideOpen	Entry OtherWideOpen	Entry MyEqualRgn****************************************************************** rDrawPixel** The picture contains the following information**      OpCode (already read if gotten here)*      OrigSCB*      BW vs Color (0 = color, non zero	= bw)*      Width of pixels*      BoundsRect*      SrcRect*      DestRect*      Mode*      (Rgn if it exists)*      Image** The color vs bw word is for future enhancement so that we* can have 640 mode	undithered stretching.** Change History** 12 Dec 88	Steven Glass** The strip routine below moved the stack down instead of up* when an error occured, causing the system to crash.** 14 Jun 89	Steven Glass** Locked handle being allocated for the pixel image.  This* prevents it from moving when stdPixels gets memory.*****************************************************************rDrawPixel	PROC EXPORT	jsr GetPicWord	; get orig SCB	bcs Error0	pha	jsr GetPicWord	; ignore color vs bw indicator	bcs Error2	jsr GetPicWord	; get the SrcWidth out of pic	bcs Error2	pha	pha	; src bounds	pha	pha	pha	tsc	inc a	pea 0	pha	PushWord #8	jsl CallGetPic	bcs Error12	pha	; src rect	pha	pha	pha	tsc	inc a	pea 0	pha	PushWord #8	jsl CallGetPic	bcs Error20	pha	; DestRect	pha	pha	pha	tsc	inc a	pea 0	pha	PushWord #8	jsl CallGetPic	bcs Error28	jsr MapThisRect	; now map the dest rect	jsr GetPicWord	; Get transfer mode	bcs Error28	pha	bra SkipErrorsError36		;	ldx #36	bra StripError32		;	ldx #32	bra StripError28		;	ldx #28	bra StripError20		;	ldx #20	bra StripError12		;	ldx #12Strip		;	pha	; save error code on stack	phx	; save amount to strip on stack	tsc	clc	adc 1,s	plx	; get amount to strip off stack	plx	; get error code	tcs	; adjust stack	txa	; fix a-reg	sec	; set carryError0	rtsError2	plx	rtsSkipErrors		;;----------------------------------------------------------;; Now deal with the	mask rgn (if any);	PushLong #WideOpen	; start by assuming	this	lda OpCodeToDo	and #$0001	beq NoRgn	jsr GetPicRgn	; get the region	bcs Error32	phx	; Put handle on stack	pha	sta 5,s	; and store over WideOpen handle	txa	sta 7,s	jsr MapThisRgn	bcs Error36NoRgn		;	phd	; switch to Quickdraw's zp to	lda QuickDrawD	; figure out how much memory	tcd	; we need to hold pixel map.	jsl PortLoc2ZP	ply	; put orig d in y	pla	sta RgnHandleC	pla	sta RgnHandleC+2	pla	sta XferMode	pla	sta DestRect	pla	sta DestRect+2	pla	sta DestRect+4	pla	sta DestRect+6	pla	sta SrcRect	pla	sta SrcRect+2	pla	sta SrcRect+4	pla	sta SrcRect+6	pla	sta SrcBounds	pla	sta SrcBounds+2	pla	sta SrcBounds+4	pla	sta SrcBounds+6	pla	sta SrcWidth	pla	; get orig SCB	and #$0080	beq OrigWas320	lda DestSCB	and #$0080	bne NoAdjust	lsr SrcRect+2	lsr SrcRect+6	lsr SrcBounds+2	lsr SrcBounds+6	bra NoAdjustOrigWas320		;	lda DestSCB	and #$0080	beq NoAdjust	asl SrcRect+2	asl SrcRect+6	asl SrcBounds+2	asl SrcBounds+6NoStretchRgn		;NoAdjust		;	lda SrcBounds+4	;	sec	sbc SrcBounds	ldx SrcWidth	phy	pld	; switch back to actually multiply	pha	; space for result	pha	pha	phx	_Multiply	lda 1,s	; get handle of this size	jsr MyWNewHandle	; but leave size on	stack	bcs Error4NH	; changed name to signify uniqueness	sta TempDataPtr	; put handle here and save on stack	stx TempDataPtr+2	phx	pha;-----------------------------------------------------------;; Lock this memory because it could move when calling; std pixels.;; SEG 14 Jun 89;	ldy #4	lda [TempDataPtr],y	ora #$8000	sta [TempDataPtr],y;; End 14 Jun 89 Fix;-----------------------------------------------------------	jsr DerefTempDataPtr	pei TempDataPtr+2	; read data out of picture	pei TempDataPtr	lda 9,s	pha	jsl CallGetPic	bcs Error8	lda 1,s	; get handle again	sta TempDataPtr	lda 3,s	sta TempDataPtr+2	jsr DerefTempDataPtr ; deref again	ldx QuickdrawD	; put pointer to data in QD's zp	lda TempDataPtr	sta >SrcPixelMapRef,x	lda TempDataPtr+2	sta >SrcPixelMapRef+2,x	phd	; switch to QD's zp	txa	tcd	lda DestSCB	; force SrcSCB to be same as DestSCB	sta SrcSCB	jsl SetupPortRegions	lda #o_StdPixels	; display it	jsl CallStdPlay	lda RgnHandleC	cmp #WideOpen	bne MustDisposeRgn	lda RgnHandleC+2	cmp #^WideOpen	beq NoDisposeRgnMustDisposeRgn	pei RgnhandleC+2	pei RgnHandleC	_DisposehandleNoDisposeRgn		;	pld	; back to play direct page	_DisposeHandle	pla	; get rid of handle	size from	pla	; stack	rtsError8		;	ldx #12	brl Strip;; 9/6/90	Mensch; The above strip code seems to have been modified to yank 12 bytes instead of 8 bytes.; Andy found a bug where when this Error4 was called the wrong number of bytes was being; yanked off the stack. So, I am going to first assume that Error8 was fixed right and error ; 4 was not (see the code for details..). In order for this to work right we must also force; an error message into <A> so that the picture is exited properly.Error4NH	ldx #8	; was ldx #4	lda #$0201	; since this is only after new handle, say out of memory	brl Strip	Export Rect320Rect320	DC.W 0,0,200,320	Export Rect640Rect640		;	DC.W 0,0,200,640	ENDP****************************************************************** wDrawPixel** We will put the following information	in the picture** Opcode	          (2 bytes)* Adjusted Row Bytes          (2 bytes)* Adjusted Bounds Rect        (8 bytes)* SrcRect	          (8 bytes)* DestRect	          (8 bytes)* Mode	          (2 bytes)* MaskRgn (if any)	          (rgn size	bytes)* Bitmap data	          (x rows of byte data)** In deciding how much information to save we are faced with a* little work.  The	source pixel map may have a bunch of unneeded* information around the source rect.	See image below** .......................................* .......................................* .........-----------...................* .........!.........!......unusefull....* .........!..good...!.......data........* .........!..data...!...................* .........!.........!...................* .........-----------...................* .......................................** We can easily throw away the unused slices above and below the* image.  A little more difficult is the data to the left and* right of the image.** We can do this fairly easily by only putting into the picture* the bytes containing used data.****************************************************************** wDrawPixel     STARTwDrawPixel	PROC EXPORT;----------------------------------------------------;; Reserve Space on the stack for the adjusted; src bounds rect and the adjusted width	pei SrcBounds+6	pei SrcBounds+4	pei SrcBounds+2	pei SrcBounds	pei SrcWidthsAdjWidth	equ 1AdjBounds	equ 3CurLinePtr	equ MinRect	; these are temporary re-use ofAdjWidth	equ CurLinePtr+4	; the min rectNumLines	equ AdjWidth+2;----------------------------------------------------;; Look at src rect and bounds rect and see if there; are any lines we can skip;	lda SrcPixelMapRef	sta CurLinePtr	lda SrcPixelMapRef+2	sta CurLinePtr+2	lda SrcRect	sec	sbc SrcBounds	beq NoTopSkip	pha	; space for result	pha	pha	pei SrcWidth	_Multiply	pla	clc	adc CurLinePtr	sta CurLinePtr	pla	adc CurLinePtr+2	sta CurLinePtr+2	lda SrcRect	; adjust the bounds	rect on stack	sta AdjBounds,sNoTopSkip		;	lda SrcRect+4	cmp SrcBounds+4	bpl BotOK	sta AdjBounds+4,sBotOK		;;----------------------------------------------------;; CurLinePtr now points to first scan line in pixel map; that we will save	from.  Now lets see	if we can; save fewer than SrcWidth bytes per scan line.;; Start by seeing if we start with the first; byte of first scan line.  If not add the offset; to CurLinePtr;	lda SrcRect+2	sec	sbc SrcBounds+2	lsr a	bit SrcSCB-1	bpl Mode320_1	lsr aMode320_1		;	  ; this is offset of byte having first	pha	; pixel in it (save	this a minute)	clc	adc CurLinePtr	sta CurLinePtr	bcc NoCarry1	inc CurLinePtr+2NoCarry1		;	lda 1,s	; now adjust the left edge of	asl a	; the bounds rect	bit SrcSCB-1	bpl Mode320_2	asl aMode320_2	clc	adc AdjBounds+2+2,s	sta AdjBounds+2+2,s;----------------------------------------------------;; Now I calculate how many bytes per scan line to; save.;	lda SrcRect+6	; calculate the offset to byte having	dec a	; last pixel in it (dec for qd's rep 	sec	; of rects)	sbc SrcBounds+2	lsr a	bit SrcSCB-1	bpl Mode320_3	lsr aMode320_3		;	  ; Width = Last - First + 1	sec	;	sbc 1,s	;	plx	; get rid of value on stack 	inc a	;	sta AdjWidth	; put on zp and on stack	sta sAdjWidth,s	lda SrcRect+6	cmp SrcBounds+6	bpl RightOK	sta AdjBounds+6,sRightOK		;;----------------------------------------------------;; Finally, I calculate the number of scan lines to; save.;	lda AdjBounds+4,s	; changed 27 May 88, SEG to use 	sec	; adjusted bounds instead of SrcRect	sbc AdjBounds,s	; End Change	sta NumLines;----------------------------------------------------;; The calculations are done so lets save the sucker.; First, I must decide if this is an OpBitsRect; or an OpBitsRgn.	To make this decision, I look at; the rgn in RgnHandleC.  If this rgn is the WideOpen; rgn, then we use the Rect op code.  If it is not; the wideopen rgn,	then the poor fool who made this; call is trying to	clip the pixel map to a mask rgn;; Now you would think that the easiest way to decide; if the wide open rgn was in RgnHandleC would be; to compare RgnHandleC to WideOpen.  This is how; we almost shipped	version 1.0.  Unfortunately; it does not quite	work and may ORCA spend many; many, many, many,	many, many, many, many, many, many; many, many years in purgatory for it.;; The source for ROM version 1.0 has the following code in it;          WideOpen	dc i4'There';	ds 2;          There	dc i'-32767/2,-32767/2,32767/2,32767/2';; The source for ROM version 2.0 has the following code in it;          WideOpen	dc i4'There';	ds 2;          There	dc i'-32767/2,-32767/2,32767/2,32767/2';; THE ROMS DO NOT HAVE THE SAME VALUES IN THEM FOR WIDE OPEN; BECAUSE THE ASSEMBLER CHANGED FROM VERSION 1.0 TO VERSION	2.0.;; There was a bug in the assembler we used to make ROM 1.0.	 -32767/2; became $C000.  It	should be $C001.;	PushLong #WideOpen	PushLong RgnHandleC	jsr MyEqualRgn	bcs ItsOpBitsRect	PushLong #OtherWideOpen	PushLong RgnHandleC	jsr MyEqualRgn	bcs ItsOpBitsRect	lda #PicBitsRgn	bra PutOpCodeItsOpBitsRect	lda #PicBitsRectPutOpCode	pha	; save it on the stack	jsr putpicword	; and put it in the	picture	bcs Error12;----------------------------------------------------------;; Now put in the orig SCB;	lda SrcSCB	jsr PutPicWord	bcs Error12;----------------------------------------------------------;; Next the color vs	bw indicator.;	lda #0	jsr PutPicWord	bcs Error12; put adjusted width and bounds rect.	tsc	inc a	inc a	inc a	pea 0	pha	PushWord #10	jsl CallPutPic	bcs Error12	ply	; this is copy of opcode	pla	; clean the ten bytes off the stack	pla	pla	pla	pla	phy	; put it back; SrcRect	tdc	clc	adc #SrcRect	pea 0	pha	PushWord #8	jsl CallPutPic	bcs Error2; DestRect	tdc	clc	adc #DestRect	pea 0	pha	PushWord #8	jsl CallPutPic	bcs Error2	bra GoToModeError12	plx	plx	plx	plxError4	plxError2	plxError0	rtsGoToMode		;; Mode	lda XferMode	jsr PutPicWord	bcs Error2; Region if PicBitsRgn	pla	cmp #PicBitsRect	beq NotARegion	ldx RgnHandleC	ldy RgnHandleC+2	jsr PutPicRgnC	bcs Error0NotARegion		;; Finally the data	lda NumLines	beq NonePixelMapLoop		;	pei CurLinePtr+2	; point to current	pei CurLinePtr	pei AdjWidth	jsl CallPutPic	bcs Error0	lda CurLinePtr	clc	adc SrcWidth	sta CurLinePtr	bcc NoCarry2	inc CurLinePtr+2NoCarry2		;	dec NumLines	bne PixelMapLoopNone; If we get this far we know no error has occured, so clear the carry to indicate that no error; has occured.	clc	rts	ENDP******************************************************************* MyEqualRgn******************************************************************* MyEqualRgn     STARTMyEqualRgn	PROC EXPORT	definestackOrigD	wordRtsAdr	wordRgn1	longRgn2	long	phd	tsc	tcd	lda [Rgn1]	tax	ldy #2	lda [Rgn1],y	sta Rgn1+2	stx Rgn1	lda [Rgn2]	tax	lda [Rgn2],y	sta Rgn2+2	stx Rgn2	lda [Rgn1]	cmp [Rgn2]	bne NotEqual	tay	dey	deyLoop	lda [Rgn1],y	cmp [Rgn2],y	bne NotEqual	dey	dey	bne Loop	secGetOut	pld	ply	pla	pla	pla	pla	phy	rtsNotEqual	clc	bra GetOut	ENDP* OtherWideOpen  STARTOtherWideOpen	PROC EXPORT	DC.L There	DS.B 2There	DC.W 10,$C000,$C000,$3FFF,$3FFF	ENDP****************************************************************** WideOpen** This is a fake region containing a bounding box equal* to the potential drawing space.*****************************************************************WideOpen	PROC 	DC.L There	DS.B 2There	DC.W 10	DC.W -MaxInt,-MaxInt,MaxInt,MaxInt	ENDP	END